-- ---------- 3. 人工复核：内容不可靠，移出公共题库 ----------
-- (a) 解析自相矛盾：该题解析由两道题的解析拼接而成（前半段以「故正确答案为D」
--     收尾，后半段又以「故正确答案为C」收尾），与选项标注的答案互相矛盾。
UPDATE `question` SET `audit_status` = 'PENDING' WHERE `id` = 3067;
-- (b) 题干清洗后为空：这些题的题干原本就只有页脚（如「第4页，共25页」），
--     说明题干正文在解析阶段就已丢失，共 19 条。
UPDATE `question` SET `audit_status` = 'PENDING' WHERE `id` IN (3078, 3099, 3121, 3123, 3124, 3125, 3127, 3137, 3160, 3301, 3315, 3321, 3325, 3343, 3345, 3346, 3348, 3349, 3378);

-- ---------- 自检 ----------
SELECT COUNT(*) AS 仍含水印 FROM `question` WHERE `subject_id` = 190 AND (`stem` LIKE '%一站式备考%' OR `analysis` LIKE '%一站式备考%');
SELECT COUNT(*) AS 仍含页脚 FROM `question` WHERE `subject_id` = 190 AND (`stem` REGEXP '第[ ]*[0-9]+[ ]*页' OR `analysis` REGEXP '第[ ]*[0-9]+[ ]*页');
SELECT COUNT(*) AS 仍含App答案头 FROM `question` WHERE `subject_id` = 190 AND `analysis` LIKE '正确答案：%';
